"""Report rendering: venue-format Markdown + machine-readable JSON."""

from __future__ import annotations

import json
from dataclasses import MISSING
from dataclasses import fields as dc_fields
from typing import Any

from . import __version__
from .models import (
    ActionItem,
    Aggregate,
    MetaReview,
    Review,
    ReviewReport,
    RunInfo,
    StructuredPaper,
    Usage,
    dataclass_to_dict,
    param_support,
)
from .venues import Venue

HONESTY_NOTE = (
    "Prebuttal is a pre-submission stress test, not a score predictor. "
    "Each review above was generated by the listed model in an isolated context; "
    "treat the aggregate as a signal about weaknesses to fix before the real "
    "Reviewers 1-3 see the paper."
)


def _fmt_score(v: float | None, maximum: float | None = None) -> str:
    if v is None:
        return "n/a"
    s = f"{v:g}"
    return f"{s} / {maximum:g}" if maximum is not None else s


def _dispersion_label(agg: Aggregate, max_rating: float) -> str:
    if agg.std is None or agg.n == 0:
        return ""
    norm = agg.std / max_rating * 10 if max_rating else 0
    if norm < 0.8:
        return "low disagreement"
    if norm < 1.6:
        return "moderate disagreement"
    return "HIGH disagreement — reviewers are split"


NOT_APPLIED = "n/a"
PARAM_NOTE = (
    f"{NOT_APPLIED} = the backend does not take this parameter, so the model's own default "
    "was used (agent CLIs and relay take neither; current Claude API models accept only "
    "their default sampling and have no seed; OpenAI reasoning models take no temperature)."
)


def _params(backend: str, model: str, temperature: float, seed: int | None) -> tuple[str, str]:
    """Temperature and seed as displayed: the value only where the backend applied it."""
    temp_ok, seed_ok = param_support(backend, model)
    return (
        f"{temperature:g}" if temp_ok else NOT_APPLIED,
        str(seed) if seed_ok and seed is not None else NOT_APPLIED,
    )


def _bar(value: float, maximum: float) -> str:
    filled = max(0, min(round(value), int(maximum)))
    return "█" * filled + "░" * max(0, int(maximum) - filled)


def _render_review(review: Review, venue: Venue, index: int) -> str:
    out = [f"## Review {index}: {review.reviewer_id} — persona `{review.persona}`", ""]
    model = review.model or "CLI default"
    temp, seed = _params(review.backend, review.model, review.temperature, review.seed)
    effort = f" · effort {review.effort}" if review.effort else ""
    out.append(
        f"*Backend `{review.backend}` · model `{model}`{effort} · temp {temp} "
        f"· seed {seed} · {review.duration_s:.0f}s · {review.usage.describe()}*"
    )
    out.append("")
    if review.error and not review.parse_ok:
        out.append(f"> **Failed:** {review.error}")
        out.append("")
        if review.raw_output:
            out.append("<details><summary>Raw model output</summary>")
            out.append("")
            out.append("```")
            out.append(review.raw_output[:4000])
            out.append("```")
            out.append("")
            out.append("</details>")
        return "\n".join(out)

    for f in venue.fields:
        v = review.fields.get(f.key)
        if f.kind == "score":
            anchor = f.anchor_for(v) if v is not None else ""
            anchor_s = f" — {anchor}" if anchor else ""
            out.append(f"### {f.label}: {_fmt_score(v, f.max)}{anchor_s}")
            out.append("")
        elif f.kind == "list":
            out.append(f"### {f.label}")
            out.append("")
            items = v or []
            if items:
                out += [f"- {item}" for item in items]
            else:
                out.append("*(none given)*")
            out.append("")
        else:
            out.append(f"### {f.label}")
            out.append("")
            out.append(str(v or "*(not provided)*"))
            out.append("")
    return "\n".join(out)


def render_markdown(report: ReviewReport, venue: Venue) -> str:
    r = report
    max_rating = venue.rating_field.max
    assert max_rating is not None  # rating fields always carry a scale
    out: list[str] = []

    out.append(f"# Prebuttal Report — {r.paper.title}")
    out.append("")
    out.append(
        f"> **Venue:** {venue.name} ({venue.key}) · **Generated:** {r.run.generated_at} · "
        f"**Source:** {r.run.source_type} `{r.run.source}`"
    )
    out.append(
        f"> prebuttal v{r.run.prebuttal_version} · seed {r.run.seed} · "
        f"pack {r.run.pack_chars:,} chars (sha256/{r.run.pack_sha256})"
    )
    out.append("")

    # --- predicted outcome
    agg = r.aggregate
    out.append("## Predicted outcome")
    out.append("")
    if agg.mean is not None:
        out.append(
            f"**{agg.mean:g} / {max_rating:g}** — σ {agg.std:g}, "  # noqa: RUF001
            f"range {agg.min:g}–{agg.max:g} (n={agg.n}) · {_dispersion_label(agg, max_rating)}"  # noqa: RUF001
        )
    else:
        out.append("**n/a** — no review produced a parseable rating")
    out.append("")
    for rev in r.reviews:
        persona = rev.persona
        if rev.parse_ok and rev.rating is not None:
            bar = _bar(rev.rating, max_rating)
            anchor = venue.rating_field.anchor_for(rev.rating)
            out.append(
                f"- {rev.reviewer_id} `{bar}` **{rev.rating:g}** — {anchor} "
                f"({persona}, {rev.backend})"
            )
        else:
            out.append(f"- {rev.reviewer_id} — no rating ({rev.error or 'unparseable output'})")
    out.append("")

    if r.paper.warnings:
        out.append("**Ingestion warnings:** " + "; ".join(r.paper.warnings))
        out.append("")

    # --- revision plan (the AC's, distilled from all reviews)
    if r.meta.action_plan:
        out.append("## Revision plan")
        out.append("")
        out.extend(render_plan(r.meta.action_plan))
        out.append("")

    # --- meta review
    out.append(
        f"## Meta-review (Area Chair — `{r.meta.backend}` / `{r.meta.model or 'CLI default'}`)"
    )
    out.append("")
    if r.meta.error and not r.meta.parse_ok:
        out.append(f"> **AC failed:** {r.meta.error}")
        out.append("")
    else:
        if r.meta.meta_review:
            out.append(r.meta.meta_review)
            out.append("")
        if r.meta.estimated_rating is not None:
            anchor = venue.rating_field.anchor_for(r.meta.estimated_rating)
            out.append(
                f"**AC estimate: {_fmt_score(r.meta.estimated_rating, max_rating)}"
                + (f" — {anchor}" if anchor else "")
                + "**"
            )
            out.append("")
        if r.meta.confidence is not None:
            out.append(f"AC confidence: {r.meta.confidence:g} / 5")
            out.append("")
        if r.meta.recommendation:
            out.append(f"*Recommendation:* {r.meta.recommendation}")
            out.append("")
        if r.meta.disagreements:
            out.append(f"*Disagreements:* {r.meta.disagreements}")
            out.append("")

    # --- individual reviews
    out.append("---")
    out.append("")
    for i, rev in enumerate(r.reviews, 1):
        out.append(_render_review(rev, venue, i))
        out.append("")

    # --- transparency table
    out.append("---")
    out.append("")
    out.append("## Backend transparency")
    out.append("")
    out.append("| Reviewer | Persona | Backend | Model | Effort | Temp | Seed |")
    out.append("|---|---|---|---|---|---|---|")
    for rev in r.reviews:
        temp, seed = _params(rev.backend, rev.model, rev.temperature, rev.seed)
        out.append(
            f"| {rev.reviewer_id} | {rev.persona} | `{rev.backend}` | "
            f"`{rev.model or 'CLI default'}` | {rev.effort or 'default'} | {temp} | {seed} |"
        )
    temp, seed = _params(r.meta.backend, r.meta.model, r.meta.temperature, r.run.seed)
    out.append(
        f"| AC | area_chair | `{r.meta.backend}` | `{r.meta.model or 'CLI default'}` | "
        f"{r.meta.effort or 'default'} | {temp} | {seed} |"
    )
    roles = [(rev.backend, rev.model) for rev in r.reviews] + [(r.meta.backend, r.meta.model)]
    if any(param_support(b, m) != (True, True) for b, m in roles):
        out.append("")
        out.append(f"*{PARAM_NOTE}*")
    out.append("")
    out.append(f"Total usage: {r.usage_total.describe()}.")
    out.append("")

    out.append("---")
    out.append("")
    out.append(f"*{HONESTY_NOTE}*")
    out.append("")
    return "\n".join(out)


def render_plan(items: list[ActionItem], *, checkboxes: bool = True) -> list[str]:
    """The revision plan as Markdown list lines (``- [ ]`` task items by default)."""
    lines = []
    for it in items:
        box = "- [ ] " if checkboxes else "- "
        tags = ", ".join(it.raised_by)
        extra = " · ".join(x for x in (tags, f"effort: {it.effort}" if it.effort else "") if x)
        line = f"{box}**{it.priority}** — {it.issue}"
        if it.action:
            line += f" → {it.action}"
        if extra:
            line += f" ({extra})"
        lines.append(line)
    return lines


def _applied(backend: str, model: str) -> dict[str, bool]:
    temp_ok, seed_ok = param_support(backend, model)
    return {"temperature_applied": temp_ok, "seed_applied": seed_ok}


def to_json(report: ReviewReport, venue: Venue) -> dict[str, Any]:
    r = report
    return {
        "prebuttal_version": __version__,
        "generated_at": r.run.generated_at,
        "venue": _venue_json(venue),
        "run": dataclass_to_dict(r.run),
        "paper": r.paper.summary_dict(),
        "aggregate": {
            **dataclass_to_dict(r.aggregate),
            "rating_scale": venue.rating_field.max,
        },
        "reviewers": [
            {
                **dataclass_to_dict(rev),
                **_applied(rev.backend, rev.model),
                "rating_label": venue.rating_field.anchor_for(rev.rating)
                if rev.rating is not None
                else None,
            }
            for rev in r.reviews
        ],
        "meta": {**dataclass_to_dict(r.meta), **_applied(r.meta.backend, r.meta.model)},
        "usage_total": dataclass_to_dict(r.usage_total),
        "notice": HONESTY_NOTE,
    }


def _venue_json(venue: Venue) -> dict[str, Any]:
    out: dict[str, Any] = {"key": venue.key, "name": venue.name}
    if venue.custom:  # keep the definition: the file may change or move later
        from .venues.custom import venue_to_spec

        out["custom"] = True
        out["definition"] = venue_to_spec(venue)
    return out


def dumps_json(report: ReviewReport, venue: Venue) -> str:
    return json.dumps(to_json(report, venue), indent=2, ensure_ascii=False)


def _dataclass_from(cls: Any, data: dict[str, Any]) -> Any:
    known = {f.name: f for f in dc_fields(cls)}
    kwargs = {k: v for k, v in data.items() if k in known and k != "usage"}
    if "usage" in known and isinstance(data.get("usage"), dict):
        kwargs["usage"] = Usage(**data["usage"])
    # stored summaries omit some fields (e.g. paper.abstract): fill required
    # gaps with empty values; renderers only read what the JSON carries.
    for name, f in known.items():
        if name in kwargs or f.default is not MISSING or f.default_factory is not MISSING:
            continue
        ann = str(f.type)
        kwargs[name] = [] if "list" in ann else ("" if "str" in ann else 0)
    return cls(**kwargs)


def _meta_from(d: dict[str, Any]) -> MetaReview:
    meta = _dataclass_from(MetaReview, d)
    meta.action_plan = [
        _dataclass_from(ActionItem, a) for a in d.get("action_plan") or [] if isinstance(a, dict)
    ]
    return meta


def report_from_dict(d: dict[str, Any]) -> ReviewReport:
    """Rebuild a report from its ``report.json`` (enough to re-render HTML)."""
    venue = d.get("venue")
    return ReviewReport(
        paper=_dataclass_from(StructuredPaper, d["paper"]),
        venue_key=venue.get("key", "") if isinstance(venue, dict) else str(venue or ""),
        reviews=[_dataclass_from(Review, r) for r in d["reviewers"]],
        meta=_meta_from(d["meta"]),
        aggregate=_dataclass_from(Aggregate, d["aggregate"]),
        run=_dataclass_from(RunInfo, d["run"]),
    )
